r=Path('Tools/LiteralGen');created=[]
for packet in sorted((r/'packets/de-en-ru/11_1KI').glob('*_007*.txt')):
 b=next(x for x in packet.read_text().split('==TARGET ')[1:] if x.startswith('lang=ru '));vs=[int(x) for x in re.findall(r'^#(\d+) ',b,re.M)];p=r/'outputs/ru/11_1KI'/(packet.stem+'.tsv');assert not p.exists();p.parent.mkdir(parents=True,exist_ok=True);out=[]
 for v in vs:
  a,b=rows[v-1];assert len(b.split())<=60 and '\t' not in a+b and '\n' not in a+b;out.append(f'{v}\t{a}\t{b}')
 with p.open('x') as f:f.write('\n'.join(out)+'\n')
 created.append(str(p))
q=Path('.literalgen-state/de-en-ru/11_1KI-root-native-created.json');a=json.loads(q.read_text());a.extend(created);q.write_text(json.dumps(a,ensure_ascii=False,indent=2));print('RU007',len(created),'files',51,'rows exclusively created')
